style.css:
/* YouTube Y2K */

html, body, ytd-app {
    background: linear-gradient(135deg,#ffd6f6,#d6f3ff,#e6d6ff) fixed !important;
}

ytd-masthead {
    background: rgba(255,255,255,.55) !important;
    backdrop-filter: blur(18px);
}

ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer {
    background: rgba(255,255,255,.35) !important;
    backdrop-filter: blur(12px);
    border: 2px solid #ffb6e6 !important;
    border-radius: 22px !important;
    box-shadow: 0 0 18px #ffb6e6, 0 0 28px #9fdcff;
    transition: .25s;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover,
ytd-grid-video-renderer:hover {
    transform: scale(1.03);
    box-shadow: 0 0 30px #ff8fd8, 0 0 45px #7fdfff;
}

button,
tp-yt-paper-button,
input {
    border-radius: 20px !important;
    border: 2px solid #ffc8ec !important;
}

a:hover {
    color: #ff66c4 !important;
    text-shadow: 0 0 10px #ffb6e6;
}

::-webkit-scrollbar {
    width: 12px;
}

::-webkit-scrollbar-thumb {
    background: linear-gradient(#ff9edb,#aee8ff,#d0b3ff);
    border-radius: 20px;
}
